const assets = '/app/benchmark/assets';

function safeImage(slide, file, opts) {
  const p = path.join(assets, file);
  if (fs.existsSync(p)) slide.addImage({ path: p, ...opts });
}
function rect(slide, x, y, w, h, color, transparency = 0, lineColor = color, radius = false) {
  slide.addShape(radius ? S.roundRect : S.rect, {
    x, y, w, h,
    fill: { color, transparency },
    line: { color: lineColor, transparency: lineColor === color ? 100 : 0, width: 0.6 }
  });
}
function line(slide, x, y, w, color = C.line, width = 1) {
  slide.addShape(S.line, { x, y, w, h: 0, line: { color, width } });
}
function title(slide, text, opts = {}) {
  slide.addText(text, {
    x: opts.x ?? 0.55, y: opts.y ?? 0.3, w: opts.w ?? 11.6, h: opts.h ?? 0.55,
    fontFace: 'Aptos Display', fontSize: opts.size ?? 25, bold: true,
    color: opts.color ?? C.darkText, margin: 0, fit: 'shrink'
  });
