}
function footer(slide, n, dark=false) {
  slide.addText('OpenRouter Rankings · latest week of March 2025', {
    x: 0.55, y: 7.05, w: 4.6, h: 0.18, fontSize: 7.5, color: dark ? 'CBD5E1' : C.slate, margin: 0
